// test_config_engine_golden.cpp — CLI-driven golden runs for the frozen
// model constants (plan constants-yaml §6/§8).
//
// task-06 decision 1: the fixtures are now committed under
// `tests/fixtures/` (tiny 8x8 AOI, generated by
// `tests/fixtures/make_golden_fixtures.py`). No `data/` directory is
// needed, so a fresh clone runs this test. Missing fixtures or a missing
// engine binary are FAILURES, never silent skips (task-01 B6).
//
// Scenario 1: 5 days, seed 42, no transmission. State COG + both sidecars
// must be byte-identical to the golden.
//
// Scenario 2: 90 days with --enable-transmission + host_static population.
// `--initial-vector-infected-frac 0.2` guarantees the vector→human branch
// on the tiny AOI; the daily log is frozen byte-for-byte and the assertions
// prove the fixture really carries the full chain (not an all-zero run).
#include <gtest/gtest.h>

#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <optional>
#include <string>
#include <vector>

namespace fs = std::filesystem;

namespace {

constexpr int kSeed = 42;
constexpr int kDays = 5;
const char* kBox = "0.0,5.7,0.07223082372340844,5.771873683468865";

struct Fixtures {
    fs::path abm_dir;      // mal-core/src/mal_core/abm
    fs::path fixture_dir;  // .../tests/fixtures
    fs::path golden_dir;   // .../tests/golden
};

std::optional<Fixtures> find_fixtures() {
    fs::path dir = fs::current_path();
    for (int i = 0; i < 8; ++i) {
        const fs::path abm = dir / "mal-core" / "src" / "mal_core" / "abm";
        const fs::path fixtures = abm / "tests" / "fixtures";
        const fs::path golden = abm / "tests" / "golden";
        if (fs::exists(fixtures / "tiny_env.nc") &&
            fs::exists(fixtures / "tiny_habitat.gpkg") &&
            fs::exists(golden / "state_seed42_day5.tif")) {
            return Fixtures{abm, fixtures, golden};
        }
        if (!dir.has_parent_path()) break;
        dir = dir.parent_path();
    }
    return std::nullopt;
}

fs::path engine_binary() {
#ifdef MAL_ABM_FAST_ENGINE_BIN
    return fs::path(MAL_ABM_FAST_ENGINE_BIN);
#else
    return {};
#endif
}

// Largest numeric value of `"key": <number>` in a JSON text file (-1 if
// the key never appears). Used to prove the frozen transmission log
// actually carries the SEIR-SEI chain.
double max_field_value(const fs::path& json_path, const std::string& key) {
    std::ifstream in(json_path);
    if (!in.good()) return -1.0;
    const std::string text((std::istreambuf_iterator<char>(in)),
                           std::istreambuf_iterator<char>());
    const std::string needle = "\"" + key + "\":";
    double best = -1.0;
    for (size_t pos = text.find(needle);
         pos != std::string::npos;
         pos = text.find(needle, pos + needle.size())) {
        const char* start = text.c_str() + pos + needle.size();
        char* end = nullptr;
        const double value = std::strtod(start, &end);
        if (end != start && value > best) best = value;
    }
    return best;
}

void expect_files_equal(const fs::path& produced, const fs::path& golden) {
    ASSERT_TRUE(fs::exists(produced))
        << "produced file missing: " << produced;
    ASSERT_TRUE(fs::exists(golden)) << "golden missing: " << golden;
    std::ifstream a(produced, std::ios::binary);
    std::ifstream b(golden, std::ios::binary);
    ASSERT_TRUE(a.good() && b.good());
    for (long long offset = 0;; ++offset) {
        const int ca = a.get();
        const int cb = b.get();
        EXPECT_EQ(ca, cb) << "byte " << offset
                          << " of " << produced.filename().string()
                          << " differs from golden";
        if (ca < 0 || cb < 0) break;
    }
}

fs::path temp_dir_for(const std::string& tag) {
    const fs::path dir = fs::temp_directory_path() /
                         (tag + "_" + std::to_string(::getpid()));
    fs::create_directories(dir);
    return dir;
}

}  // namespace

TEST(ConfigEngineGolden, TinyAoiSeed42FiveDaysBitIdentical) {
    auto fixtures = find_fixtures();
    ASSERT_TRUE(fixtures.has_value())
        << "golden fixtures missing: mal-core/src/mal_core/abm/tests/"
           "fixtures/tiny_{env.nc,habitat.gpkg} + tests/golden/"
           "state_seed42_day5.tif must exist under a parent of "
        << fs::current_path()
        << " (regenerate with tests/fixtures/make_golden_fixtures.py)";
    const fs::path bin = engine_binary();
    ASSERT_FALSE(bin.empty()) << "MAL_ABM_FAST_ENGINE_BIN not defined";
    ASSERT_TRUE(fs::exists(bin)) << "engine binary not linked: " << bin;

    const fs::path out_dir = temp_dir_for("mal_abm_golden");
    const std::string out_tif = (out_dir / "state.tif").string();

    std::string cmd = bin.string() +
        " run --bbox " + kBox + " --crs EPSG:4326"
        " --resolution-m 1000 --year 2024 --month 1"
        " --seed " + std::to_string(kSeed) +
        " --days " + std::to_string(kDays) +
        " --n-adults-per-detection 1000"
        " --env " + (fixtures->fixture_dir / "tiny_env.nc").string() +
        " --habitat " + (fixtures->fixture_dir / "tiny_habitat.gpkg").string() +
        " --output " + out_tif;
    const int rc = std::system(cmd.c_str());
    ASSERT_EQ(rc, 0) << "engine run failed: " << cmd;

    expect_files_equal(out_tif,
                       fixtures->golden_dir / "state_seed42_day5.tif");
    expect_files_equal(out_dir / "state.json",
                       fixtures->golden_dir / "state_seed42_day5.json");
    expect_files_equal(out_dir / "state_aquatic.json",
                       fixtures->golden_dir / "state_seed42_day5_aquatic.json");
}

TEST(ConfigEngineGolden, TinyAoiTransmissionChainBitIdentical) {
    auto fixtures = find_fixtures();
    ASSERT_TRUE(fixtures.has_value())
        << "golden fixtures missing: mal-core/src/mal_core/abm/tests/"
           "fixtures/* must exist under a parent of " << fs::current_path();
    const fs::path bin = engine_binary();
    ASSERT_FALSE(bin.empty()) << "MAL_ABM_FAST_ENGINE_BIN not defined";
    ASSERT_TRUE(fs::exists(bin)) << "engine binary not linked: " << bin;

    const fs::path out_dir = temp_dir_for("mal_abm_golden_tx");
    const std::string out_tif = (out_dir / "state.tif").string();
    const std::string tx_log = (out_dir / "transmission_log.json").string();

    std::string cmd = bin.string() +
        " run --bbox " + kBox + " --crs EPSG:4326"
        " --resolution-m 1000 --year 2024 --month 1"
        " --seed " + std::to_string(kSeed) +
        " --days 90 --n-adults-per-detection 1000"
        " --enable-transmission --initial-vector-infected-frac 0.2"
        " --env " + (fixtures->fixture_dir / "tiny_env.nc").string() +
        " --habitat " + (fixtures->fixture_dir / "tiny_habitat.gpkg").string() +
        " --hosts " + (fixtures->fixture_dir / "tiny_hosts.nc").string() +
        " --output " + out_tif +
        " --emit-transmission-log " + tx_log;
    const int rc = std::system(cmd.c_str());
    ASSERT_EQ(rc, 0) << "engine transmission run failed: " << cmd;

    expect_files_equal(
        tx_log, fixtures->golden_dir / "transmission_seed42_day90.json");

    // Guard against a degenerate all-zero fixture: the frozen log must
    // carry the full chain (human→vector→EIP→bites→human).
    EXPECT_GT(max_field_value(tx_log, "E_V"), 0.0);
    EXPECT_GT(max_field_value(tx_log, "I_V"), 0.0);
    EXPECT_GT(max_field_value(tx_log, "infectious_bites"), 0.0);
    EXPECT_GT(max_field_value(tx_log, "E_H"), 0.0);
}

// task-06 decision 5: a transmission log named like the state sidecar is
// rejected before any rollout runs (it would be overwritten).
TEST(ConfigEngineGolden, CollidingTransmissionLogPathIsRejected) {
    auto fixtures = find_fixtures();
    ASSERT_TRUE(fixtures.has_value()) << "golden fixtures missing";
    const fs::path bin = engine_binary();
    ASSERT_FALSE(bin.empty()) << "MAL_ABM_FAST_ENGINE_BIN not defined";
    ASSERT_TRUE(fs::exists(bin)) << "engine binary not linked: " << bin;

    const fs::path out_dir = temp_dir_for("mal_abm_golden_collision");
    const std::string out_tif = (out_dir / "state.tif").string();
    const std::string colliding = (out_dir / "state.json").string();

    std::string cmd = bin.string() +
        " run --bbox " + kBox + " --crs EPSG:4326"
        " --resolution-m 1000 --year 2024 --month 1"
        " --seed " + std::to_string(kSeed) + " --days 1"
        " --enable-transmission --initial-vector-infected-frac 0.2"
        " --env " + (fixtures->fixture_dir / "tiny_env.nc").string() +
        " --habitat " + (fixtures->fixture_dir / "tiny_habitat.gpkg").string() +
        " --hosts " + (fixtures->fixture_dir / "tiny_hosts.nc").string() +
        " --output " + out_tif +
        " --emit-transmission-log " + colliding;
    const int rc = std::system(cmd.c_str());
    EXPECT_NE(rc, 0) << "collision should be rejected: " << cmd;
    EXPECT_FALSE(fs::exists(colliding))
        << "collision path must not be written: " << colliding;
}

// Same guard, diagnostic sidecars: the engine writes `_aquatic.json`
// unconditionally (submodel present) and `_foci.json` on outbreak.
TEST(ConfigEngineGolden, CollidingDiagnosticSidecarPathsAreRejected) {
    auto fixtures = find_fixtures();
    ASSERT_TRUE(fixtures.has_value()) << "golden fixtures missing";
    const fs::path bin = engine_binary();
    ASSERT_FALSE(bin.empty()) << "MAL_ABM_FAST_ENGINE_BIN not defined";
    ASSERT_TRUE(fs::exists(bin)) << "engine binary not linked: " << bin;

    for (const std::string suffix : {"_aquatic.json", "_foci.json"}) {
        const fs::path out_dir =
            temp_dir_for("mal_abm_golden_collision" + suffix);
        const std::string out_tif = (out_dir / "state.tif").string();
        const std::string colliding = (out_dir / ("state" + suffix)).string();

        std::string cmd = bin.string() +
            " run --bbox " + kBox + " --crs EPSG:4326"
            " --resolution-m 1000 --year 2024 --month 1"
            " --seed " + std::to_string(kSeed) + " --days 1"
            " --enable-transmission --initial-vector-infected-frac 0.2"
            " --env " + (fixtures->fixture_dir / "tiny_env.nc").string() +
            " --habitat " + (fixtures->fixture_dir / "tiny_habitat.gpkg").string() +
            " --hosts " + (fixtures->fixture_dir / "tiny_hosts.nc").string() +
            " --output " + out_tif +
            " --emit-transmission-log " + colliding;
        const int rc = std::system(cmd.c_str());
        EXPECT_NE(rc, 0) << "collision with " << suffix
                         << " should be rejected: " << cmd;
        EXPECT_FALSE(fs::exists(colliding))
            << "collision path must not be written: " << colliding;
    }
}

// With N rollouts the requested log stem is replaced by one file per
// rollout: `transmission_seed%04d.json`. Pin the names so a future path
// helper cannot silently overwrite rollout i-1.
TEST(ConfigEngineGolden, MultiRolloutTransmissionLogNamesAreUnique) {
    auto fixtures = find_fixtures();
    ASSERT_TRUE(fixtures.has_value()) << "golden fixtures missing";
    const fs::path bin = engine_binary();
    ASSERT_FALSE(bin.empty()) << "MAL_ABM_FAST_ENGINE_BIN not defined";
    ASSERT_TRUE(fs::exists(bin)) << "engine binary not linked: " << bin;

    const fs::path out_dir = temp_dir_for("mal_abm_golden_multi_tx");
    const std::string out_tif = (out_dir / "state.tif").string();
    const std::string requested = (out_dir / "transmission_log.json").string();

    std::string cmd = bin.string() +
        " run --bbox " + kBox + " --crs EPSG:4326"
        " --resolution-m 1000 --year 2024 --month 1"
        " --seed " + std::to_string(kSeed) + " --days 1"
        " --n-rollouts 2"
        " --enable-transmission --initial-vector-infected-frac 0.2"
        " --env " + (fixtures->fixture_dir / "tiny_env.nc").string() +
        " --habitat " + (fixtures->fixture_dir / "tiny_habitat.gpkg").string() +
        " --hosts " + (fixtures->fixture_dir / "tiny_hosts.nc").string() +
        " --output " + out_tif +
        " --emit-transmission-log " + requested;
    const int rc = std::system(cmd.c_str());
    ASSERT_EQ(rc, 0) << "multi-rollout run failed: " << cmd;

    EXPECT_TRUE(fs::exists(out_dir / "transmission_seed0000.json"));
    EXPECT_TRUE(fs::exists(out_dir / "transmission_seed0001.json"));
    EXPECT_FALSE(fs::exists(requested))
        << "the shared requested path must not be written for N>1";
}
